import { Component, OnInit } from '@angular/core';
import { FormControl } from '@angular/forms';
import { BehaviorSubject } from 'rxjs';
import { CountryService } from './country.service';
import { Country } from './types';
// import {ngTemplateOutlet} from '@angular/common';

@Component({
  selector: 'app-exercise1',
  templateUrl: './exercise1.component.html',
  styleUrls: ['./exercise1.component.css']
})
export class Exercise1Component implements OnInit {
  countries$ = new BehaviorSubject<Country[]>([]);
  currCountry = '';

  mySelectControl = new FormControl<Country['id']>(null);
  // countryDropdown = new FormControl<Country['id']>(null);
  constructor(private service: CountryService) { }

  ngOnInit() {
    this.countries$ = this.service.getCountries() as BehaviorSubject<Country[]>;
  }
}
<h2>Exercise 1 my 02-1</h2>
<h3>Your mission is to turn the following dropdown into a country-selection dropdown. </h3>
<img src="assets/exercise1.gif" />
<ol>
  <li>Open a terminal in your project <code>ng-advanced-workshop</code></li>
  <li>Run <code>npm run server</code> to start the sample back-end that holds the data needed for all exercises</li>
  <li>Update the code in <code>app/exercise1</code> so that our component loads its list of countries from <code>http://localhost:3000/countries</code></li>
  <li>Display the total number of countries in the corresponding <code>div</code></li>
  <li>Selecting a country should result in the <code>id</code> of the country being set as the dropdown value</li>
</ol>
<h4>You can take a look at the expected result here: <a routerLink="/solution/1">http://localhost:4200/solution/1</a> </h4>
<hr>
<h2>Result</h2>
<!-- Edit the code down below to implement the requested features -->
<div>
  <div>Select one of {{ (countries$ | async)?.length - 1 || 0 }} countries:</div>
  <!-- <div>Select one of {{ countries$ | async | json }} countries:</div> -->

</div>

  <ng-container *ngIf="countries$ | async as countries">


     <select #countryName [formControl]="mySelectControl" *ngIf="countries.length > 0">
       <option *ngFor="let country of countries">
        {{country.description}}
       </option>
     </select>
     <div>Current value: {{countries[mySelectControl.value] | json}}</div>
     <!-- <div>Current value: {{countryName.value}}</div> -->

  </ng-container>
